param([string]$ExcelPath=".\CONSULTA INVENTARIO.xlsx",[string]$OutputPath=".\asignaciones.json")
$ErrorActionPreference="Stop";$Salt="INV-GENERAL-2026-V1"
function T($v){if($null-eq$v){return""};([string]$v).Trim()};function N($v){(T $v).ToUpperInvariant()-replace'[^A-Z0-9]',''};function H($t){$s=[Security.Cryptography.SHA256]::Create();try{return-join($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($t))|%{$_.ToString('x2')})}finally{$s.Dispose()}}
$xl=New-Object -ComObject Excel.Application;$xl.Visible=$false;$xl.DisplayAlerts=$false
try{$wb=$xl.Workbooks.Open([IO.Path]::GetFullPath($ExcelPath),0,$true);$ws=$wb.Worksheets.Item('LISTADO');$tb=$ws.ListObjects.Item('DETALLE');$h=@{};for($c=1;$c-le$tb.ListColumns.Count;$c++){$h[[string]$tb.HeaderRowRange.Cells.Item(1,$c).Text]=$c};$out=@();$seen=@{};for($r=1;$r-le$tb.DataBodyRange.Rows.Count;$r++){$a=(T $tb.DataBodyRange.Cells.Item($r,$h['ACTIVO']).Value2).ToUpperInvariant();$en=N $tb.DataBodyRange.Cells.Item($r,$h['ENUMBER']).Value2;if($a-notin@('SI','SÍ','TRUE','1','ACTIVO')-or!$en-or$en-eq'ENCRIPTADO'-or$seen.ContainsKey($en)){continue};$seen[$en]=$true;$out+=[pscustomobject]@{id=H "$Salt|$en";pareja=T $tb.DataBodyRange.Cells.Item($r,$h['N° PAREJA']).Text;mesa=T $tb.DataBodyRange.Cells.Item($r,$h['MESA']).Text;listado=T $tb.DataBodyRange.Cells.Item($r,$h['LISTADO']).Text;ubicacion=T $tb.DataBodyRange.Cells.Item($r,$h['UBICACIÓN A CONTAR']).Text;breakManana=T $tb.DataBodyRange.Cells.Item($r,$h['HORARIO BREAK MAÑANA']).Text;almuerzo=T $tb.DataBodyRange.Cells.Item($r,$h['HORARIO DE ALMUERZO']).Text;breakTarde=T $tb.DataBodyRange.Cells.Item($r,$h['HORARIO BREAK TARDE']).Text}};[IO.File]::WriteAllText([IO.Path]::GetFullPath($OutputPath),(ConvertTo-Json -InputObject @($out|Sort-Object id)-Depth 4),(New-Object Text.UTF8Encoding($false)));Write-Host "[OK] Registros: $($out.Count)" -ForegroundColor Green}finally{if($wb){$wb.Close($false)};$xl.Quit()}